-- Hand-written: grants, row-level security and checks. Purchases are financial records: no DELETE.
GRANT SELECT, INSERT, UPDATE ON "tenant"."utility_purchases" TO safezone_app;
GRANT SELECT, INSERT ON "tenant"."utility_purchase_events" TO safezone_app;
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['utility_purchases','utility_purchase_events'] LOOP
    EXECUTE format('ALTER TABLE "tenant".%I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE "tenant".%I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format($p$CREATE POLICY %I ON "tenant".%I FOR ALL TO safezone_app
      USING (estate_id = nullif(current_setting('app.estate_id', true), '')::uuid)
      WITH CHECK (estate_id = nullif(current_setting('app.estate_id', true), '')::uuid)$p$, t || '_tenant', t);
  END LOOP;
END $$;
ALTER TABLE "tenant"."utility_purchases" ADD CONSTRAINT utility_purchases_status_check CHECK (status IN
  ('created','paid','vending','vended','failed','refund_pending','refunded'));
ALTER TABLE "tenant"."utility_purchases" ADD CONSTRAINT utility_purchases_amounts_check
  CHECK (amount > 0 AND fee >= 0 AND total = amount + fee);
-- A token exists only after vending (utilities.md rule 1).
ALTER TABLE "tenant"."utility_purchases" ADD CONSTRAINT utility_purchases_token_check
  CHECK (token_wrapped IS NULL OR status = 'vended');
CREATE TRIGGER utility_purchase_events_append_only BEFORE UPDATE OR DELETE ON "tenant"."utility_purchase_events"
  FOR EACH ROW EXECUTE FUNCTION audit.reject_mutation();
